"""Data-safety tests use generated bytes in a private temporary workspace only."""

import contextlib
from compression import zstd
import gzip
import importlib.util
import io
import json
import lzma
import os
from pathlib import Path
import random
import struct
import tempfile
import unittest
from unittest.mock import patch
import zipfile
import zlib

ROOT = Path(__file__).resolve().parents[2]
spec = importlib.util.spec_from_file_location(
    'cache_archive_tests', ROOT / 'scripts/cache-archive.py'
)
archive = importlib.util.module_from_spec(spec)
spec.loader.exec_module(archive)


class CacheArchiveTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='2dsketcher-cache-case-')
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.source = self.root / '.local/fixture'
        self.source.mkdir(parents=True)
        (self.root / 'evidence/cleanup/run-01').mkdir(parents=True)
        self.patches = [
            patch.object(archive, 'ROOT', self.root),
            patch.object(archive, 'STORE', self.root / 'store'),
            patch.object(archive, 'ALLOWED', {'fixture'}),
            patch.object(archive, 'assert_inactive', lambda source: None),
        ]
        for item in self.patches:
            item.start()
            self.addCleanup(item.stop)

    def call(self, function):
        with contextlib.redirect_stdout(io.StringIO()):
            function('fixture')

    def test_raw_zip_bytes_deduplicate_and_restore_exactly(self):
        payload = random.Random(7).randbytes(128 * 1024)
        for number in range(8):
            with zipfile.ZipFile(
                self.source / f'{number}.zip', 'w', compression=zipfile.ZIP_DEFLATED
            ) as output:
                output.writestr('metadata.json', json.dumps({'revision': number}))
                output.writestr('shared-binary.bin', payload)
        original = {path.name: path.read_bytes() for path in self.source.iterdir()}
        self.call(archive.pack)
        stored = sum(
            path.stat().st_size for path in (self.root / 'store/objects').iterdir()
        )
        self.assertLess(stored, sum(map(len, original.values())) / 4)
        self.call(archive.verify)
        self.call(archive.evict)
        self.assertFalse(self.source.exists())
        self.call(archive.restore)
        self.assertEqual(
            {path.name: path.read_bytes() for path in self.source.iterdir()}, original
        )
        first_result = (
            self.root / 'evidence/cleanup/run-01/fixture-evicted.json'
        ).read_bytes()
        self.call(archive.evict)
        self.assertFalse(self.source.exists())
        self.assertEqual(
            (self.root / 'evidence/cleanup/run-01/fixture-evicted.json').read_bytes(),
            first_result,
        )

    def test_changed_source_is_retained_and_restore_will_not_overwrite_it(self):
        target = self.source / 'project.bin'
        target.write_bytes(b'original')
        self.call(archive.pack)
        self.call(archive.verify)
        target.write_bytes(b'newer-user-edit')
        self.call(archive.evict)
        self.assertEqual(target.read_bytes(), b'newer-user-edit')
        with self.assertRaisesRegex(ValueError, 'E_CACHE_RESTORE_EXISTS'):
            self.call(archive.restore)

    def test_index_traversal_is_rejected_before_any_source_is_removed(self):
        target = self.source / 'keep.bin'
        target.write_bytes(b'keep')
        outside = self.root / 'outside.bin'
        outside.write_bytes(b'outside')
        self.call(archive.pack)
        self.call(archive.verify)
        index = self.root / 'store/indexes/fixture.jsonl.gz'
        with gzip.open(index, 'at', encoding='utf-8') as stream:
            stream.write(
                json.dumps(
                    {
                        'path': '../outside.bin',
                        'chunks': [],
                        'bytes': 0,
                        'sha256': archive.digest(b''),
                    }
                )
                + '\n'
            )
        with self.assertRaisesRegex(ValueError, 'E_CACHE_ENTRY|E_CACHE_INDEX_CHANGED'):
            self.call(archive.evict)
        self.assertEqual(target.read_bytes(), b'keep')
        self.assertEqual(outside.read_bytes(), b'outside')

    def test_corrupt_object_cannot_authorize_eviction(self):
        (self.source / 'keep.bin').write_bytes(random.Random(8).randbytes(10000))
        self.call(archive.pack)
        self.call(archive.verify)
        obj = next((self.root / 'store/objects').glob('*.raw'))
        data = bytearray(obj.read_bytes())
        data[0] ^= 255
        obj.write_bytes(data)
        with self.assertRaisesRegex(ValueError, 'E_CACHE_OBJECT_HASH'):
            self.call(archive.evict)
        self.assertTrue((self.source / 'keep.bin').exists())

    def test_group_traversal_and_unapproved_roots_are_rejected(self):
        for name in ['../outside', 'generated-../../outside', 'user-projects']:
            with self.assertRaisesRegex(ValueError, 'E_CACHE_GROUP'):
                archive.group_path(name)

    def test_previous_candidates_never_evict_the_active_version(self):
        previous = self.source / '2DSketcher-win32-x64-0.22.4.zip'
        current = self.source / '2DSketcher-win32-x64-0.22.5.zip'
        previous.write_bytes(b'previous')
        current.write_bytes(b'current')
        package = self.root / 'package.json'
        with (
            patch.object(archive, 'group_path', return_value=self.source),
            contextlib.redirect_stdout(io.StringIO()),
        ):
            archive.pack('previous-candidates')
            package.write_text('{"version":"0.22.4"}')
            with self.assertRaisesRegex(ValueError, 'E_CACHE_CURRENT_PACKAGE'):
                archive.evict('previous-candidates')
            self.assertTrue(previous.exists())
            package.write_text('{"version":"0.22.5"}')
            archive.evict('previous-candidates')
            self.assertFalse(previous.exists())
            self.assertEqual(current.read_bytes(), b'current')
            archive.restore('previous-candidates')
            self.assertEqual(previous.read_bytes(), b'previous')

    def test_packed_small_files_restore_individual_bytes_and_reject_invalid_slices(
        self,
    ):
        originals = {
            'one.txt': b'first' * 1000,
            'two.txt': b'second' * 1500,
            'empty': b'',
        }
        for name, data in originals.items():
            (self.source / name).write_bytes(data)
        with patch.object(archive, 'SMALL_FILE_GROUPS', {'fixture'}):
            self.call(archive.pack)
        index = self.root / 'store/indexes/fixture.jsonl.gz'
        with gzip.open(index, 'rt', encoding='utf-8') as rows:
            slices = [r for line in rows if 'offset' in (r := json.loads(line))]
        self.assertEqual(len(slices), 2)
        self.assertEqual(slices[0]['chunks'], slices[1]['chunks'])
        objects = archive.Objects(self.root / 'store/objects')
        with self.assertRaisesRegex(ValueError, 'E_CACHE_SLICE'):
            list(archive.record_bytes({**slices[0], 'offset': archive.BLOCK}, objects))
        self.call(archive.evict)
        self.call(archive.restore)
        self.assertEqual(
            {p.name: p.read_bytes() for p in self.source.iterdir()}, originals
        )

    def test_interrupted_research_restore_can_be_retried(self):
        (self.source / 'model.bin').write_bytes(b'original')
        self.call(archive.pack)
        self.call(archive.evict)
        with patch.object(archive.os, 'utime', side_effect=OSError('disk')):
            with self.assertRaises(OSError):
                self.call(archive.restore)
        self.assertFalse(self.source.exists())
        self.call(archive.restore)
        self.assertEqual((self.source / 'model.bin').read_bytes(), b'original')

    def test_overlapping_isolated_groups_restore_without_overwriting_edits(self):
        with patch.object(archive, 'group_path', return_value=self.source):
            first = self.source / 'first.bin'
            first.write_bytes(b'first')
            archive.pack('isolated')
            archive.evict('isolated')
            self.source.mkdir()
            second = self.source / 'second.bin'
            second.write_bytes(b'second')
            archive.pack('isolated-later')
            archive.evict('isolated-later')
            archive.restore('isolated')
            archive.restore('isolated-later')
            archive.restore('isolated')
            self.assertEqual(second.read_bytes(), b'second')
            first.write_bytes(b'edited')
            with self.assertRaisesRegex(ValueError, 'E_CACHE_RESTORE_EXISTS'):
                archive.restore('isolated')
            self.assertEqual(first.read_bytes(), b'edited')

    def test_restore_checks_free_space_before_creating_destination(self):
        (self.source / 'keep.bin').write_bytes(b'keep')
        self.call(archive.pack)
        self.call(archive.verify)
        self.call(archive.evict)
        with patch.object(
            archive.shutil,
            'disk_usage',
            return_value=archive.shutil._ntuple_diskusage(100, 99, 1),
        ):
            with self.assertRaisesRegex(ValueError, 'E_CACHE_RESTORE_SPACE'):
                self.call(archive.restore)
        self.assertFalse(self.source.exists())

    def test_shuffle_is_exact_for_ragged_lengths(self):
        for length in [*range(20), 1023, 1024, 1025]:
            original = random.Random(length).randbytes(length)
            self.assertEqual(archive.unshuffle4(archive.shuffle4(original)), original)

    def test_all_cold_codecs_reconstruct_the_same_logical_object(self):
        original = bytes(range(251)) * 20
        key = archive.digest(original)
        folder = self.root / 'codecs'
        folder.mkdir()
        for codec in archive.CODECS:
            with self.subTest(codec=codec):
                data = (
                    archive.shuffle4(original) if codec.startswith('s4') else original
                )
                if codec.endswith('zst'):
                    data = zstd.compress(data)
                elif codec.endswith('xz'):
                    data = lzma.compress(
                        data, filters=[{'id': lzma.FILTER_LZMA2, 'dict_size': 1024**2}]
                    )
                elif codec.endswith('z'):
                    data = zlib.compress(data)
                file = folder / (key + '.' + codec)
                file.write_bytes(data)
                self.assertEqual(archive.Objects(folder).get(key), original)
                file.unlink()

    def test_cold_decoding_rejects_oversize_and_truncated_objects(self):
        with patch.object(archive, 'BLOCK', 64):
            for codec, encode in [
                ('z', zlib.compress),
                ('xz', lzma.compress),
                ('zst', zstd.compress),
            ]:
                with self.subTest(codec=codec):
                    with self.assertRaises(ValueError):
                        archive.decode_object(encode(b'x' * 65), codec)
                    with self.assertRaises(ValueError):
                        archive.decode_object(encode(b'x' * 50)[:-1], codec)

    def test_cold_compaction_preserves_float_bytes_without_quantization(self):
        spec = importlib.util.spec_from_file_location(
            'test_compact', ROOT / 'scripts/cache-compact.py'
        )
        compact = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(compact)
        original = b''.join(struct.pack('<f', float(index)) for index in range(32768))
        previous_size = len(zlib.compress(original))
        codec, payload = min(
            compact.candidates(original, previous_size), key=lambda row: len(row[1])
        )
        self.assertLess(len(payload), previous_size * 0.95)
        self.assertEqual(archive.decode_object(payload, codec), original)
        store = self.root / 'store'
        folder = store / 'objects'
        folder.mkdir(parents=True)
        key = archive.digest(original)
        (folder / (key + '.raw')).write_bytes(original)
        with (
            patch.object(compact, 'ROOT', self.root),
            patch.object(compact.archive, 'STORE', store),
            patch.object(compact.archive, 'running_commands', return_value=[]),
            patch('sys.argv', ['cache-compact.py', '--fast']),
            contextlib.redirect_stdout(io.StringIO()),
        ):
            compact.main()
        self.assertEqual(archive.Objects(folder).get(key), original)
        self.assertFalse((folder / (key + '.raw')).exists())
        self.assertLess(sum(p.stat().st_size for p in folder.iterdir()), previous_size)

    def test_changed_bytes_with_preserved_metadata_are_never_evicted(self):
        file = self.source / 'keep.bin'
        file.write_bytes(b'original')
        stamp = file.stat().st_mtime_ns
        self.call(archive.pack)
        file.write_bytes(b'changed!')
        os.utime(file, ns=(stamp, stamp))
        self.call(archive.verify)
        self.call(archive.evict)
        self.assertEqual(file.read_bytes(), b'changed!')

    def test_metadata_change_is_rejected_by_archive_verification(self):
        file = self.source / 'keep.bin'
        file.write_bytes(b'original')
        self.call(archive.pack)
        file.write_bytes(b'new file with a different size')
        with self.assertRaisesRegex(ValueError, 'E_CACHE_SOURCE_CHANGED'):
            self.call(archive.verify)

    def test_reclaim_validates_backup_and_preserves_unindexed_new_files(self):
        (self.source / 'original.bin').write_bytes(b'original')
        self.call(archive.pack)
        (self.source / 'new.bin').write_bytes(b'new data')
        self.call(archive.evict)
        self.assertFalse((self.source / 'original.bin').exists())
        self.assertEqual((self.source / 'new.bin').read_bytes(), b'new data')
        report = json.loads(
            (self.root / 'evidence/cleanup/run-01/fixture-evicted.json').read_text()
        )
        self.assertEqual(report['remainingSelectedFiles'], 1)
        self.assertTrue(report['wholeArchiveReconstructedBeforeFirstRemoval'])
        self.assertTrue(report['sourceHashRecheckedBeforeEachRemoval'])

    def test_corruption_before_first_reclaim_prevents_all_removal(self):
        (self.source / 'keep.bin').write_bytes(b'keep')
        self.call(archive.pack)
        obj = next((self.root / 'store/objects').iterdir())
        obj.write_bytes(b'corrupt')
        with self.assertRaises(ValueError):
            self.call(archive.evict)
        self.assertTrue((self.source / 'keep.bin').exists())

    def test_index_change_during_validation_prevents_first_removal(self):
        (self.source / 'keep.bin').write_bytes(b'keep')
        self.call(archive.pack)
        original = archive.verified_records
        index = self.root / 'store/indexes/fixture.jsonl.gz'

        def changed(name):
            yield from original(name)
            data = bytearray(index.read_bytes())
            data[4] ^= 1
            index.write_bytes(data)

        with patch.object(archive, 'verified_records', changed):
            with self.assertRaisesRegex(ValueError, 'E_CACHE_INDEX_CHANGED'):
                self.call(archive.evict)
        self.assertTrue((self.source / 'keep.bin').exists())


if __name__ == '__main__':
    unittest.main()
